server.createContext("/articles/2", exchange -> {
    // "2" jest CZESCIA tozsamosci - GET /articles/2 zawsze zwraca DOKLADNIE ten artykul
    respond(exchange, 200, "{\"id\":2,\"title\":\"Wprowadzenie do REST\"}");
});
// GET /articles/999999 (nieistniejacy id) -> 404 Not Found, nie "pusta kolekcja"

server.createContext("/articles", exchange -> {
    Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
    String category = params.getOrDefault("category", "all");        // domyslnie: wszystkie
    boolean includeDrafts = Boolean.parseBoolean(params.getOrDefault("includeDrafts", "false"));
    // GET /articles                                    -> category=all, includeDrafts=false
    // GET /articles?category=tech                       -> TYLKO kategoria tech, bez szkicow
    // GET /articles?category=tech&includeDrafts=true     -> kategoria tech, WLACZNIE ze szkicami
});

// ZLE: identyfikator zasobu jako query param, nie jako segment sciezki
server.createContext("/articles", exchange -> {
    Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
    String id = params.get("id"); // "2" trafia jako filtr, nie jako czesc tozsamosci zasobu
    // GET /articles?id=2 - wyglada jak filtrowanie kolekcji, a w rzeczywistosci to 1 konkretny zasob
});

// DOBRZE: identyfikator w SCIEZCE, filtry w QUERY PARAMS
server.createContext("/articles/2", exchange -> { /* konkretny artykul o id=2 */ });
server.createContext("/articles", exchange -> {
    Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
    String category = params.get("category"); // TO jest prawdziwy filtr kolekcji
});
